// Exports the Valen core's step from the Wasm module as "step". The header is generated by
// valec from health.vale, so a signature change there fails to compile here.
#include "health/step.h"

__attribute__((export_name("step")))
ValeInt wasm_step(ValeInt autoRespawn, ValeInt isAlive, ValeInt receivedHealth, ValeInt event, double health) {
  return health_step(autoRespawn, isAlive, receivedHealth, event, health);
}
